# phs/baiying/event_log.py
from __future__ import annotations

import asyncio
import json
import os
import uuid
from collections import Counter, defaultdict
from copy import deepcopy
from datetime import datetime, timezone
from pathlib import Path
from threading import RLock
from typing import Any, Dict, List, Optional

from fastapi import APIRouter, HTTPException, Query, Request
from fastapi.responses import StreamingResponse
from pydantic import BaseModel, Field


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _ts(value: Optional[str]) -> float:
    if not value:
        return 0.0
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp()
    except Exception:
        return 0.0


def _dump(model: BaseModel) -> Dict[str, Any]:
    if hasattr(model, "model_dump"):
        return model.model_dump(exclude_none=True)
    return model.dict(exclude_none=True)


class EventCreate(BaseModel):
    type: str = Field(default="pipeline_step", description="pipeline_step/tts_play/comment_match/popup_show/alert_fire")
    severity: str = Field(default="info", description="debug/info/warning/error/critical")
    title: str = ""
    message: str = ""
    source: str = "phs"
    payload: Dict[str, Any] = Field(default_factory=dict)


class EventStore:
    valid_types = {"pipeline_step", "tts_play", "comment_match", "popup_show", "alert_fire"}
    valid_severity = {"debug", "info", "warning", "error", "critical"}

    def __init__(self, path: Optional[str] = None, max_events: int = 5000):
        default_path = Path("data") / "event_log" / "events.json"
        self.path = Path(path or os.getenv("PHS_EVENT_LOG_DB", default_path))
        self.max_events = max_events
        self.lock = RLock()
        self.data: Dict[str, Any] = {"events": []}
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            self._save()
            return
        try:
            self.data = json.loads(self.path.read_text(encoding="utf-8"))
            self.data.setdefault("events", [])
            self.data["events"] = self.data["events"][-self.max_events:]
        except Exception:
            self.path.replace(self.path.with_suffix(".corrupt.json"))
            self.data = {"events": []}
            self._save()

    def _save(self) -> None:
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.data, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(self.path)

    def append(self, payload: EventCreate | Dict[str, Any]) -> Dict[str, Any]:
        item = _dump(payload) if isinstance(payload, BaseModel) else dict(payload)
        event_type = item.get("type") or "pipeline_step"
        severity = item.get("severity") or "info"
        if event_type not in self.valid_types:
            event_type = "pipeline_step"
        if severity not in self.valid_severity:
            severity = "info"

        event = {
            "id": item.get("id") or uuid.uuid4().hex,
            "type": event_type,
            "severity": severity,
            "title": item.get("title", ""),
            "message": item.get("message", ""),
            "source": item.get("source", "phs"),
            "payload": item.get("payload", {}),
            "created_at": item.get("created_at") or _now(),
        }
        with self.lock:
            self.data["events"].append(event)
            self.data["events"] = self.data["events"][-self.max_events:]
            self._save()
        return deepcopy(event)

    def query(
        self,
        event_type: Optional[str] = None,
        severity: Optional[str] = None,
        since: Optional[str] = None,
        until: Optional[str] = None,
        q: Optional[str] = None,
        limit: int = 200,
    ) -> List[Dict[str, Any]]:
        start, end = _ts(since), _ts(until) or float("inf")
        with self.lock:
            items = deepcopy(self.data["events"])

        if event_type:
            items = [x for x in items if x.get("type") == event_type]
        if severity:
            items = [x for x in items if x.get("severity") == severity]
        if since or until:
            items = [x for x in items if start <= _ts(x.get("created_at")) <= end]
        if q:
            ql = q.lower()
            items = [
                x for x in items
                if ql in (
                    x.get("title", "")
                    + x.get("message", "")
                    + x.get("source", "")
                    + json.dumps(x.get("payload", {}), ensure_ascii=False)
                ).lower()
            ]
        return items[-max(1, min(limit, 1000)):][::-1]

    def stats(self) -> Dict[str, Any]:
        with self.lock:
            items = deepcopy(self.data["events"])
        by_type = Counter(x.get("type", "unknown") for x in items)
        by_severity = Counter(x.get("severity", "info") for x in items)
        by_source = Counter(x.get("source", "phs") for x in items)
        recent_errors = [
            x for x in reversed(items)
            if x.get("severity") in {"error", "critical"}
        ][:20]
        hourly: Dict[str, int] = defaultdict(int)
        for x in items:
            key = (x.get("created_at") or "")[:13]
            if key:
                hourly[key] += 1
        return {
            "total": len(items),
            "max_events": self.max_events,
            "by_type": dict(by_type),
            "by_severity": dict(by_severity),
            "by_source": dict(by_source),
            "hourly": dict(sorted(hourly.items())),
            "recent_errors": recent_errors,
        }


class EventBus:
    def __init__(self, store: EventStore):
        self.store = store
        self.lock = RLock()
        self.subscribers: List[asyncio.Queue] = []

    def subscribe(self) -> asyncio.Queue:
        queue: asyncio.Queue = asyncio.Queue(maxsize=200)
        with self.lock:
            self.subscribers.append(queue)
        return queue

    def unsubscribe(self, queue: asyncio.Queue) -> None:
        with self.lock:
            self.subscribers = [q for q in self.subscribers if q is not queue]

    def publish(self, payload: EventCreate | Dict[str, Any]) -> Dict[str, Any]:
        event = self.store.append(payload)
        with self.lock:
            subscribers = list(self.subscribers)
        for queue in subscribers:
            try:
                queue.put_nowait(event)
            except asyncio.QueueFull:
                try:
                    queue.get_nowait()
                    queue.put_nowait(event)
                except Exception:
                    pass
        return event

    def subscriber_count(self) -> int:
        with self.lock:
            return len(self.subscribers)


class EventStream:
    def __init__(self, bus: EventBus):
        self.bus = bus

    @staticmethod
    def _format(event: Dict[str, Any]) -> str:
        event_type = event.get("type", "message")
        data = json.dumps(event, ensure_ascii=False)
        return f"event: {event_type}\ndata: {data}\n\n"

    async def stream(self, request: Request):
        queue = self.bus.subscribe()
        try:
            yield ": connected\n\n"
            while True:
                if await request.is_disconnected():
                    break
                try:
                    event = await asyncio.wait_for(queue.get(), timeout=15)
                    yield self._format(event)
                except asyncio.TimeoutError:
                    yield ": heartbeat\n\n"
        finally:
            self.bus.unsubscribe(queue)


def create_event_log_router(bus: Optional[EventBus] = None, prefix: str = "") -> APIRouter:
    event_store = bus.store if bus else EventStore()
    event_bus = bus or EventBus(event_store)
    event_stream = EventStream(event_bus)
    router = APIRouter(prefix=prefix, tags=["event-log"])

    @router.get("/events/stream")
    async def stream_events(request: Request):
        return StreamingResponse(
            event_stream.stream(request),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "Connection": "keep-alive"},
        )

    @router.get("/events/query")
    def query_events(
        type: Optional[str] = None,
        severity: Optional[str] = None,
        since: Optional[str] = None,
        until: Optional[str] = None,
        q: Optional[str] = None,
        limit: int = Query(default=200, ge=1, le=1000),
    ) -> Dict[str, Any]:
        items = event_store.query(event_type=type, severity=severity, since=since, until=until, q=q, limit=limit)
        return {"items": items, "count": len(items)}

    @router.get("/events/stats")
    def get_stats() -> Dict[str, Any]:
        data = event_store.stats()
        data["subscribers"] = event_bus.subscriber_count()
        return data

    @router.post("/events")
    def publish_event(payload: EventCreate) -> Dict[str, Any]:
        try:
            return event_bus.publish(payload)
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc))

    return router


class EventLogProvider:
    provider_id = "event_log"
    name = "Event Log"
    version = "0.1.0"

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.store = EventStore(self.config.get("db_path"))
        self.bus = EventBus(self.store)
        self.stream = EventStream(self.bus)
        self.router = create_event_log_router(self.bus)

    def get_router(self) -> APIRouter:
        return self.router

    def health(self) -> Dict[str, Any]:
        return {
            "provider": self.provider_id,
            "ok": True,
            "db_path": str(self.store.path),
            "event_count": len(self.store.data.get("events", [])),
            "subscribers": self.bus.subscriber_count(),
        }

    def metadata(self) -> Dict[str, Any]:
        return {
            "id": self.provider_id,
            "name": self.name,
            "version": self.version,
            "routes": ["/events/stream", "/events/query", "/events/stats"],
            "types": sorted(EventStore.valid_types),
            "severity": sorted(EventStore.valid_severity),
        }


def create_provider(config: Optional[Dict[str, Any]] = None) -> EventLogProvider:
    return EventLogProvider(config)


